from __future__ import annotations

from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        # employee -> {year: days_used}
        self._used: dict[str, dict[int, int]] = {}

    def _is_working_day(self, d: date) -> bool:
        # Weekends: Saturday (5) and Sunday (6)
        if d.weekday() >= 5:
            return False
        if d in self.holidays:
            return False
        return True

    def _leave_days_in_range(self, start: date, end: date) -> int:
        if end < start:
            return 0
        count = 0
        current = start
        while current <= end:
            if self._is_working_day(current):
                count += 1
            current += timedelta(days=1)
        return count

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        if end < start:
            raise ValueError("End date cannot be before start date")

        # Request must be made at least 3 days before start
        if (start - today).days < 3:
            raise ValueError("Leave request must be made at least 3 days in advance")

        days_needed = self._leave_days_in_range(start, end)

        # Determine remaining days per year; a request spanning years uses
        # the respective year's remaining balance.
        # Simplest correct approach: compute usage per year.
        usage_by_year: dict[int, int] = {}
        current = start
        while current <= end:
            if self._is_working_day(current):
                usage_by_year[current.year] = usage_by_year.get(current.year, 0) + 1
            current += timedelta(days=1)

        emp_used = self._used.setdefault(employee, {})

        # Verify each year has enough remaining
        for year, days in usage_by_year.items():
            used = emp_used.get(year, 0)
            balance = self.days_per_year - used
            if days > balance:
                raise ValueError(
                    f"Insufficient leave days for {employee} in {year}: "
                    f"need {days}, have {balance}"
                )

        # Apply usage
        for year, days in usage_by_year.items():
            emp_used[year] = emp_used.get(year, 0) + days

        return days_needed

    def remaining(self, employee: str, year: int) -> int:
        used = self._used.get(employee, {}).get(year, 0)
        return self.days_per_year - used
```

**Notes on design choices:**

- Leave balances are tracked per calendar year, and unused days automatically do not carry over because each `remaining` query computes `days_per_year - used_for_that_year` independently.
- A request spanning two calendar years is validated and deducted against each year's balance separately (so a request that crosses Dec 31 correctly handles each year's allotment).
- Weekend detection uses `weekday() >= 5` (Saturday/Sunday).
- The 3-day notice rule is enforced as `(start - today).days >= 3`, meaning a request must be submitted at least 3 calendar days before the start date.

